import{_ as e,c as o,o as a,ae as s}from"./chunks/framework.Bi6zybwU.js";const m=JSON.parse('{"title":"Post Meta Field","description":"Post Meta Field","frontmatter":{"title":"Post Meta Field","description":"Post Meta Field"},"headers":[],"relativePath":"guide/wordpress-integration/post-meta-field.md","filePath":"guide/wordpress-integration/post-meta-field.md"}'),i={name:"guide/wordpress-integration/post-meta-field.md"};function n(l,t,d,r,p,c){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="post-meta-field" tabindex="-1">Post Meta Field <a class="header-anchor" href="#post-meta-field" aria-label="Permalink to &quot;Post Meta Field&quot;">​</a></h1><p>This feature, known as <strong>Post Meta Field</strong> (also called <strong>Custom Fields</strong>), helps associate additional content to a post. With Ninja Tables, you can show this content with your table data. This content is usually not directly linked to the main content itself. Depending on the type of site, the content you’re dealing with could vary a lot. A new post can be added, or a current post can be edited. Here, an existing post is edited to build custom post meta fields in WordPress table using the Ninja Tables plugin Post Meta Field option.</p><h2 id="display-post-meta-field-in-wordpress-table" tabindex="-1">Display Post Meta Field in WordPress Table <a class="header-anchor" href="#display-post-meta-field-in-wordpress-table" aria-label="Permalink to &quot;Display Post Meta Field in WordPress Table&quot;">​</a></h2><ul><li>Firstly, navigate to your WordPress admin panel&#39;s Post <strong>Editor</strong> tab. Tap the** Screen Options** in the panel. <img src="https://ninjatables.com/wp-content/uploads/2023/01/post-meta-field-1.webp" alt="Screen Options"></li><li>And then, you will notice an expanded panel appearing. Here the <strong>Custom Fields</strong> checkbox will be visible. <img src="https://ninjatables.com/wp-content/uploads/2023/01/post-meta-field-2.webp" alt="Custom Fields checkbox"></li><li>A Custom Fields option will appear at the bottom of the post after checking the Custom Fields option. <img src="https://ninjatables.com/wp-content/uploads/2023/01/post-meta-field-3.webp" alt="Custom Fields"></li><li>The Post Meta follows a scheme called pairs of keys/values. In the above screenshot, you can see that 3 custom fields are generated with their value.</li><li>To show one of the fields in my table, go to the <strong>dashboard</strong> for Ninja Tables and add a new table, or select any of the tables that were made.</li><li>Then click on the **Add New Column **tab.</li><li>You can find the <strong>Dynamic Post Data Settings</strong> section after filling in the basic information. From there, click on the option <strong>Field</strong> <strong>Type</strong>. A drop-down option will appear. From there, click on the <strong>Post Meta</strong> option. <img src="https://ninjatables.com/wp-content/uploads/2023/01/post-meta-field-6.webp" alt="Dynamic Post Data Settings"></li><li>You will then see an input field appear to include the field value to be shown on the table. <img src="https://ninjatables.com/wp-content/uploads/2023/01/post-meta-field-7.webp" alt="field value in dynamic post data settings"></li><li>Create a Custom Field and Place the value in the <strong>Custom Fields</strong> section of your post section. **Copy **the Custom Field Value for further Use. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Post-meta-field-E-2-1024x513.png" alt="acf demo in custom field"></li><li>If** Ninja-Post** is added as a** Field Value** from the post page custom fields section, then a custom field column post meta will be added to the table. <strong>Ninja-Post</strong> is placed in the Dynamic Post Data Settings section as Field Value. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Post-meta-field-E-1-1.png" alt="field value in new column"></li><li>The final outcome of the table can be seen by clicking on the preview button. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Post-meta-field-E-3.png" alt="Preview"> Now, you can see that a post meta has been added to your table as a <strong>Custom Fields</strong> type. This is how you can display <strong>Post Meta</strong> <strong>Field</strong> of Ninja Tables.</li></ul>',4)])])}const u=e(i,[["render",n]]);export{m as __pageData,u as default};
